def transform(grid):
    from collections import Counter

    # Find background (most frequent value)
    all_vals = Counter()
    for row in grid:
        all_vals.update(row)
    background = max(all_vals.keys(), key=lambda x: all_vals[x])

    h, w = len(grid), len(grid[0])

    # Initialize output with background
    output = [[background] * w for _ in range(h)]

    # For each non-background value, spread it at intervals based on its value
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v != 0:  # Skip 0 as it's a marker, not a value to spread
                if v != background:
                    # Value v spreads at intervals of v starting from position c
                    stride = v
                    for k in range(1 + w // stride):
                        pos = c + k * stride
                        if 0 <= pos < w:
                            output[r][pos] = v
                    # Fill remaining as 0
                    for pos in range(w):
                        if output[r][pos] == background:
                            output[r][pos] = 0

    return output
